const LANGUAGES = ["en", "es", "zh", "ru", "hi", "th"];

for (const language of LANGUAGES) {
  if (!Array.isArray(messages[language]) || messages[language].length !== 500) throw new Error(`${language} must contain exactly 500 messages.`);
  if (new Set(messages[language]).size !== 500) throw new Error(`${language} contains duplicate messages.`);
}

export default messages;

export {
  LANGUAGES,
  messages
};
